97	    public function addItem(ProductId $productId, int $quantity, Money $unitPrice): void
98	    {
99	        if ($this->status !== OrderStatus::Draft) {
100	            throw InvalidOrderStateTransitionException::notAllowedInState('addItem', $this->status->value);
101	        }
102	
103	        $this->assertSameCurrency($unitPrice);
104	
105	        // Jedna položka na produkt: množství se sčítá, položka se neduplikuje.
106	        foreach ($this->lines as $existing) {
107	            if ($existing->productId->equals($productId)) {
108	                $existing->increaseQuantity($quantity);
109	                $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
110	
111	                return;
112	            }
113	        }
114	
115	        $this->lines->add(new OrderItem($this, $productId, $quantity, $unitPrice));
116	        $this->record(new OrderItemAdded($this->id, $productId, $quantity, new \DateTimeImmutable()));
117	    }
