119	    public function changeItemQuantity(ProductId $productId, int $quantity): void
120	    {
121	        if ($this->status !== OrderStatus::Draft) {
122	            throw InvalidOrderStateTransitionException::notAllowedInState('changeItemQuantity', $this->status->value);
123	        }
124	
125	        if ($quantity < 1) {
126	            throw InvalidQuantityException::mustBePositive($quantity);
127	        }
128	
129	        $this->itemFor($productId)->changeQuantity($quantity);
130	        $this->record(new OrderItemQuantityChanged($this->id, $productId, $quantity, new \DateTimeImmutable()));
131	    }
