133	    public function removeItem(ProductId $productId): void
134	    {
135	        if ($this->status !== OrderStatus::Draft) {
136	            throw InvalidOrderStateTransitionException::notAllowedInState('removeItem', $this->status->value);
137	        }
138	
139	        $item = $this->itemFor($productId);
140	        if ($this->lines->count() === 1) {
141	            throw LastItemCannotBeRemovedException::forProduct($productId);
142	        }
143	
144	        // Sleva nesmí po odebrání přesáhnout nový součet položek.
145	        $newTotal = $this->totalAmount()->subtract($item->subtotal());
146	        if ($this->discount->amountInCents > $newTotal->amountInCents) {
147	            throw DiscountExceedsItemsTotalException::forItemsTotal($this->discount, $newTotal);
148	        }
149	
150	        $this->lines->removeElement($item);
151	        $this->record(new OrderItemRemoved($this->id, $productId, new \DateTimeImmutable()));
152	    }
