154	    public function applyDiscount(Money $discount): void
155	    {
156	        if ($this->status !== OrderStatus::Draft) {
157	            throw InvalidOrderStateTransitionException::notAllowedInState('applyDiscount', $this->status->value);
158	        }
159	
160	        $this->assertSameCurrency($discount);
161	
162	        $total = $this->totalAmount();
