161	    /**
162	     * Storno z detailu objednavky (2026).
163	     *
164	     * Stornuje novy e-shop (CancelOrder): ten hlida prechod stavu, u zaplacene
165	     * objednavky zaznamena castku k vraceni a sklad uvolni rezervace.
166	     * Penize vraci obchod rucne.
167	     */
168	    public function cancelAction()
169	    {
170	        global $db;
171	        legacy_db();
172	        auth_require('obchod');
173	        if (is_post()) {
174	            csrf_check();
175	        }
176	
177	        $id = get_param('id');
178	        $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
179	        if ($order === null) {
180	            return $this->notFound('Objednávka ' . $id . ' neexistuje');
181	        }
182	        if (!is_post()) {
183	            return $this->redirect(admin_url('order', array('id' => $id)));
184	        }
185	
186	        try {
187	            legacy_command(new \App\Ordering\Application\Command\CancelOrder(
188	                \App\Ordering\Domain\ValueObject\OrderId::fromString($id),
189	                trim((string) $this->post('reason'))
190	            ));
191	        } catch (\App\Ordering\Domain\Exception\InvalidOrderStateTransitionException $e) {
192	            flash('Odeslanou ani doručenou objednávku stornovat nejde', 'error');
193	
194	            return $this->detailAction();
195	        }
196	
197	        flash('Objednávka stornována');
198	
199	        return $this->detailAction();
200	    }
201	}
