2	/**
3	 * Prihlasovani do administrace.
4	 *
5	 * Hesla jsou MD5 (2014). FIXME: prejit na password_hash, az bude cas.
6	 * Od 2024 pred administraci stoji Symfony firewall (prihlaseni, ROLE_STAFF).
7	 * Prihlaseneho uzivatele s roli predava LegacyFrontController do
8	 * $GLOBALS['LEGACY_USER'], auth_require() podle nej kontroluje roli.
9	 */
10	
11	use App\Legacy\lib\AccessDenied;
12	
13	function auth_login($login, $password)
14	{
15	    global $db;
16	    legacy_db();
17	    $user = $db->one("SELECT * FROM admin_users WHERE login = '" . $login . "' AND password_md5 = '" . md5((string) $password) . "'");
18	    if ($user === null) {
19	        return false;
20	    }
21	    $db->exec("UPDATE admin_users SET last_login = '" . date('Y-m-d H:i:s') . "' WHERE id = " . (int) $user['id']);
22	    if (session_status() === PHP_SESSION_ACTIVE) {
23	        $_SESSION['admin_id'] = $user['id'];
24	        $_SESSION['admin_login'] = $user['login'];
25	        $_SESSION['admin_role'] = $user['role'];
26	    }
27	    $GLOBALS['LEGACY_USER'] = $user;
28	    audit_log('admin_user', $user['id'], 'login');
29	
30	    return true;
31	}
32	
33	function auth_logout()
34	{
35	    if (session_status() === PHP_SESSION_ACTIVE) {
36	        unset($_SESSION['admin_id'], $_SESSION['admin_login'], $_SESSION['admin_role']);
37	    }
38	    $GLOBALS['LEGACY_USER'] = null;
39	}
40	
41	function auth_user()
42	{
43	    if (!empty($GLOBALS['LEGACY_USER'])) {
44	        return $GLOBALS['LEGACY_USER'];
45	    }
46	    if (isset($_SESSION['admin_id'])) {
47	        return db_one("SELECT * FROM admin_users WHERE id = " . (int) $_SESSION['admin_id']);
48	    }
49	
50	    return null;
51	}
52	
53	function auth_login_name()
54	{
55	    $u = auth_user();
56	
57	    return $u ? $u['login'] : 'admin';
58	}
59	
60	/**
61	 * Ma uzivatel roli? Admin muze vsechno.
62	 */
63	function auth_has_role($role)
64	{
65	    $u = auth_user();
66	    if ($u === null) {
67	        // FIXME: bez session (za Symfony firewallem) bereme jako admina
68	        return true;
69	    }
70	    if ($u['role'] == 'admin') {
71	        return true;
72	    }
73	
74	    return $u['role'] == $role;
75	}
76	
77	/**
78	 * Pusti dal jen prihlaseneho uzivatele s roli $role (admin muze vsechno),
79	 * jinak vyhodi AccessDenied (-> 403). Bez $role staci byt prihlaseny.
80	 *
81	 * Firewall pred /admin pousti jen ROLE_STAFF, roli stare administrace
82	 * (admin, obchod, sklad, ucetni) prebira LegacyFrontController z roli
83	 * Symfony uzivatele (ROLE_ADMIN, ROLE_OBCHOD, ...).
84	 */
85	function auth_require($role = null)
86	{
87	    if (auth_user() === null) {
88	        throw new AccessDenied('Nepřihlášený uživatel');
89	    }
90	    if ($role !== null && !auth_has_role($role)) {
91	        throw new AccessDenied('Nemáte oprávnění');
92	    }
93	
94	    return true;
95	}
